この章で学ぶこと

パーシャルファイル (_*.qmd) は YAML フロントマター禁止。親 (textbook.qmd) に集約します。
数式は LaTeX で記述。インラインは $E = mc^2$、ディスプレイは:


\nabla \times \mathbf{B} - \frac{1}{c}\frac{\partial \mathbf{E}}{\partial t} = \frac{4\pi}{c}\mathbf{J}
\tag{3.1}
式 3.1 は Maxwell-Ampère の法則です。

Bloch 球: OJS + Plotly.js の軽量 3D interactive
Python を起動せず、OJS だけで Plotly.js を呼ぶ例です。軽い 3D interactive を入れたい場合に向きます。


コード
{
  const container = html`&lt;div style="width: 100%; min-height: 520px;"&gt;&lt;/div&gt;`;
  const Plotly = await require("plotly.js-dist-min@2.35.2");
  const nFrames = 61;
  const thetaValues = Array.from({ length: nFrames }, (_, i) =&gt; (2 * Math.PI * i) / (nFrames - 1));
  const v0 = [0, 0, 1];

  function rotateY(vector, theta) {
    const [x, y, z] = vector;
    const c = Math.cos(theta);
    const s = Math.sin(theta);
    return [c * x + s * z, y, -s * x + c * z];
  }

  function vectorTrace(vector, color, name, width) {
    return {
      type: "scatter3d",
      mode: "lines+markers",
      x: [0, vector[0]],
      y: [0, vector[1]],
      z: [0, vector[2]],
      line: { color, width },
      marker: { size: [2, 5], color },
      name,
      hovertemplate: name + "&lt;br&gt;x=%{x:.3f}&lt;br&gt;y=%{y:.3f}&lt;br&gt;z=%{z:.3f}&lt;extra&gt;&lt;/extra&gt;",
    };
  }

  const u = Array.from({ length: 32 }, (_, i) =&gt; (2 * Math.PI * i) / 31);
  const v = Array.from({ length: 17 }, (_, i) =&gt; (Math.PI * i) / 16);
  const sphereX = u.map((uu) =&gt; v.map((vv) =&gt; Math.cos(uu) * Math.sin(vv)));
  const sphereY = u.map((uu) =&gt; v.map((vv) =&gt; Math.sin(uu) * Math.sin(vv)));
  const sphereZ = u.map(() =&gt; v.map((vv) =&gt; Math.cos(vv)));
  const orbit = thetaValues.map((theta) =&gt; rotateY(v0, theta));

  const data = [
    {
      type: "surface",
      x: sphereX,
      y: sphereY,
      z: sphereZ,
      opacity: 0.13,
      colorscale: "Greys",
      showscale: false,
      hoverinfo: "skip",
      name: "Bloch sphere",
    },
    {
      type: "scatter3d",
      mode: "lines",
      x: orbit.map((p) =&gt; p[0]),
      y: orbit.map((p) =&gt; p[1]),
      z: orbit.map((p) =&gt; p[2]),
      line: { color: "rgba(37, 99, 235, 0.35)", width: 5 },
      name: "回転軌道",
      hoverinfo: "skip",
    },
    vectorTrace(v0, "#2563eb", "初期ベクトル", 5),
    vectorTrace(rotateY(v0, 0), "#dc2626", "R_y(θ)v0", 10),
  ];

  const frames = thetaValues.map((theta, i) =&gt; {
    const p = rotateY(v0, theta);
    return {
      name: "bloch-" + i,
      data: [{ x: [0, p[0]], y: [0, p[1]], z: [0, p[2]] }],
      traces: [3],
    };
  });

  const animationOptions = {
    mode: "immediate",
    frame: { duration: 55, redraw: true },
    transition: { duration: 0 },
  };

  const layout = {
    title: "Bloch sphere: y 軸まわりの回転",
    height: 520,
    margin: { l: 0, r: 0, t: 48, b: 0 },
    scene: {
      aspectmode: "cube",
      camera: { eye: { x: 1.45, y: 1.7, z: 1.2 } },
      xaxis: { title: "X", range: [-1.25, 1.25] },
      yaxis: { title: "Y", range: [-1.25, 1.25] },
      zaxis: { title: "Z", range: [-1.25, 1.25] },
    },
    updatemenus: [
      {
        type: "buttons",
        showactive: false,
        x: 0,
        y: -0.05,
        buttons: [
          { label: "再生", method: "animate", args: [null, { ...animationOptions, fromcurrent: true }] },
          { label: "停止", method: "animate", args: [[null], { mode: "immediate", frame: { duration: 0 } }] },
        ],
      },
    ],
    sliders: [
      {
        active: 0,
        x: 0.12,
        y: -0.05,
        len: 0.84,
        steps: thetaValues.map((theta, i) =&gt; ({
          method: "animate",
          args: [["bloch-" + i], { ...animationOptions, frame: { duration: 0, redraw: true } }],
          label: Math.round((theta * 180) / Math.PI) + "°",
        })),
      },
    ],
  };

  await Plotly.newPlot(container, data, layout, { responsive: true, displaylogo: false });
  await Plotly.addFrames(container, frames);
  invalidation.then(() =&gt; Plotly.purge(container));
  return container;
}
